"""Validation script for upstream pipeline outputs (T14).

Run from the workspace root:

    python src/validate_outputs.py

Writes a JSON list of validation entries to outputs/t14_validation_summary.json.
Each entry contains: check_name, passed, message.
Missing or empty expected outputs are reported as failed checks, not crashes.
"""

import csv
import json
import os
import sys

WORKSPACE_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUTPUTS_DIR = os.path.join(WORKSPACE_ROOT, "outputs")
SUMMARY_PATH = os.path.join(OUTPUTS_DIR, "t14_validation_summary.json")

EXPECTED_FILES = [
    "t01_selected_indicators.csv",
    "t05_clean_stops.csv",
    "t08_pois_clean.csv",
    "t10_accessibility_scores.csv",
    "t13_city_clusters.csv",
]

REQUIRED_COLUMNS = {
    "t01_selected_indicators.csv": ["indicator_id", "indicator_name", "theme"],
    "t05_clean_stops.csv": ["stop_id", "stop_name", "stop_lat", "stop_lon"],
    "t08_pois_clean.csv": ["qid", "label", "poi_type", "latitude", "longitude"],
    "t10_accessibility_scores.csv": ["qid", "distance_m", "accessibility_score"],
    "t13_city_clusters.csv": ["city_id", "city_name", "year", "cluster_id"],
}


def read_csv_header_and_rowcount(path):
    """Return (header_fields, data_row_count) or raise on parse failure."""
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.reader(fh)
        try:
            header = next(reader)
        except StopIteration:
            return None, 0
        row_count = 0
        for row in reader:
            if row and any((cell or "").strip() for cell in row):
                row_count += 1
        return header, row_count


def make_entry(check_name, passed, message):
    return {
        "check_name": check_name,
        "passed": bool(passed),
        "message": str(message),
    }


def check_file_exists(filename):
    path = os.path.join(OUTPUTS_DIR, filename)
    if not os.path.isfile(path):
        return make_entry(
            "file_exists_%s" % filename,
            False,
            "Expected output file is missing: outputs/%s" % filename,
        )
    return make_entry(
        "file_exists_%s" % filename,
        True,
        "Expected output file present: outputs/%s" % filename,
    )


def check_file_nonempty(filename):
    path = os.path.join(OUTPUTS_DIR, filename)
    if not os.path.isfile(path):
        return make_entry(
            "file_nonempty_%s" % filename,
            False,
            "Cannot check size because file is missing: outputs/%s" % filename,
        )
    size = os.path.getsize(path)
    if size == 0:
        return make_entry(
            "file_nonempty_%s" % filename,
            False,
            "Output file is empty (0 bytes): outputs/%s" % filename,
        )
    return make_entry(
        "file_nonempty_%s" % filename,
        True,
        "Output file is non-empty (%d bytes): outputs/%s" % (size, filename),
    )


def check_header_and_rows(filename):
    label = "header_and_rows_%s" % filename
    path = os.path.join(OUTPUTS_DIR, filename)
    if not os.path.isfile(path):
        return make_entry(label, False, "Cannot inspect header: file missing outputs/%s" % filename)
    try:
        header, row_count = read_csv_header_and_rowcount(path)
    except Exception as exc:  # report, don't crash
        return make_entry(label, False, "Failed to parse outputs/%s: %s" % (filename, exc))
    if header is None:
        return make_entry(label, False, "Output file has no header row: outputs/%s" % filename)
    required = REQUIRED_COLUMNS.get(filename, [])
    missing_cols = [col for col in required if col not in header]
    if missing_cols:
        return make_entry(
            label,
            False,
            "outputs/%s is missing required columns: %s" % (filename, ", ".join(missing_cols)),
        )
    if row_count == 0:
        return make_entry(label, False, "outputs/%s has a header but no data rows" % filename)
    return make_entry(
        label,
        True,
        "outputs/%s has %d data rows and required columns %s"
        % (filename, row_count, ", ".join(required)),
    )


def check_t01_direction_values():
    path = os.path.join(OUTPUTS_DIR, "t01_selected_indicators.csv")
    if not os.path.isfile(path):
        return make_entry("t01_direction_values", False, "File missing: outputs/t01_selected_indicators.csv")
    valid = {"higher_is_better", "lower_is_better"}
    try:
        with open(path, newline="", encoding="utf-8") as fh:
            reader = csv.DictReader(fh)
            rows = [row for row in reader if any((v or "").strip() for v in row.values())]
    except Exception as exc:
        return make_entry("t01_direction_values", False, "Failed to parse file: %s" % exc)
    bad = [row.get("expected_direction", "").strip() for row in rows if row.get("expected_direction", "").strip() not in valid]
    if bad:
        return make_entry(
            "t01_direction_values",
            False,
            "%d row(s) with invalid expected_direction values in outputs/t01_selected_indicators.csv" % len(bad),
        )
    return make_entry(
        "t01_direction_values",
        True,
        "All %d indicator rows in outputs/t01_selected_indicators.csv have valid expected_direction values" % len(rows),
    )


def check_t05_coords():
    path = os.path.join(OUTPUTS_DIR, "t05_clean_stops.csv")
    if not os.path.isfile(path):
        return make_entry("t05_stop_coordinates", False, "File missing: outputs/t05_clean_stops.csv")
    try:
        with open(path, newline="", encoding="utf-8") as fh:
            reader = csv.DictReader(fh)
            rows = [row for row in reader if any((v or "").strip() for v in row.values())]
    except Exception as exc:
        return make_entry("t05_stop_coordinates", False, "Failed to parse file: %s" % exc)
    bad = 0
    for row in rows:
        try:
            lat = float(row["stop_lat"])
            lon = float(row["stop_lon"])
        except (KeyError, TypeError, ValueError):
            bad += 1
            continue
        if not (-90.0 <= lat <= 90.0 and -180.0 <= lon <= 180.0):
            bad += 1
    if bad:
        return make_entry(
            "t05_stop_coordinates",
            False,
            "%d stop row(s) in outputs/t05_clean_stops.csv have missing or out-of-range coordinates" % bad,
        )
    return make_entry(
        "t05_stop_coordinates",
        True,
        "All %d stops in outputs/t05_clean_stops.csv have valid coordinates" % len(rows),
    )


def check_t08_poi_types():
    path = os.path.join(OUTPUTS_DIR, "t08_pois_clean.csv")
    if not os.path.isfile(path):
        return make_entry("t08_poi_types", False, "File missing: outputs/t08_pois_clean.csv")
    try:
        with open(path, newline="", encoding="utf-8") as fh:
            reader = csv.DictReader(fh)
            rows = [row for row in reader if any((v or "").strip() for v in row.values())]
    except Exception as exc:
        return make_entry("t08_poi_types", False, "Failed to parse file: %s" % exc)
    missing = [row for row in rows if not (row.get("qid") or "").strip() or not (row.get("poi_type") or "").strip()]
    if missing:
        return make_entry(
            "t08_poi_types",
            False,
            "%d POI row(s) in outputs/t08_pois_clean.csv are missing qid or poi_type" % len(missing),
        )
    return make_entry(
        "t08_poi_types",
        True,
        "All %d POIs in outputs/t08_pois_clean.csv have qid and poi_type populated" % len(rows),
    )


def check_t10_scores():
    path = os.path.join(OUTPUTS_DIR, "t10_accessibility_scores.csv")
    if not os.path.isfile(path):
        return make_entry("t10_score_range", False, "File missing: outputs/t10_accessibility_scores.csv")
    try:
        with open(path, newline="", encoding="utf-8") as fh:
            reader = csv.DictReader(fh)
            rows = [row for row in reader if any((v or "").strip() for v in row.values())]
    except Exception as exc:
        return make_entry("t10_score_range", False, "Failed to parse file: %s" % exc)
    bad = 0
    for row in rows:
        try:
            score = float(row["accessibility_score"])
        except (KeyError, TypeError, ValueError):
            bad += 1
            continue
        if not (0.0 <= score <= 1.0):
            bad += 1
    if bad:
        return make_entry(
            "t10_score_range",
            False,
            "%d row(s) in outputs/t10_accessibility_scores.csv have accessibility_score outside [0, 1]" % bad,
        )
    return make_entry(
        "t10_score_range",
        True,
        "All %d accessibility scores in outputs/t10_accessibility_scores.csv are within [0, 1]" % len(rows),
    )


def check_t13_clusters():
    path = os.path.join(OUTPUTS_DIR, "t13_city_clusters.csv")
    if not os.path.isfile(path):
        return make_entry("t13_cluster_integrity", False, "File missing: outputs/t13_city_clusters.csv")
    try:
        with open(path, newline="", encoding="utf-8") as fh:
            reader = csv.DictReader(fh)
            rows = [row for row in reader if any((v or "").strip() for v in row.values())]
    except Exception as exc:
        return make_entry("t13_cluster_integrity", False, "Failed to parse file: %s" % exc)
    bad = 0
    clusters = set()
    for row in rows:
        try:
            cid = int(row["cluster_id"])
        except (KeyError, TypeError, ValueError):
            bad += 1
            continue
        if cid < 0:
            bad += 1
            continue
        clusters.add(cid)
    if bad:
        return make_entry(
            "t13_cluster_integrity",
            False,
            "%d row(s) in outputs/t13_city_clusters.csv have an invalid cluster_id" % bad,
        )
    return make_entry(
        "t13_cluster_integrity",
        True,
        "All %d rows in outputs/t13_city_clusters.csv have valid non-negative cluster ids (%d distinct clusters)"
        % (len(rows), len(clusters)),
    )


def main():
    entries = []
    for filename in EXPECTED_FILES:
        entries.append(check_file_exists(filename))
        entries.append(check_file_nonempty(filename))
        entries.append(check_header_and_rows(filename))
    entries.append(check_t01_direction_values())
    entries.append(check_t05_coords())
    entries.append(check_t08_poi_types())
    entries.append(check_t10_scores())
    entries.append(check_t13_clusters())

    os.makedirs(OUTPUTS_DIR, exist_ok=True)
    with open(SUMMARY_PATH, "w", encoding="utf-8") as fh:
        json.dump(entries, fh, indent=2, ensure_ascii=False)
        fh.write("\n")

    n_passed = sum(1 for e in entries if e["passed"])
    print("Validation complete: %d/%d checks passed. Summary written to %s"
          % (n_passed, len(entries), os.path.relpath(SUMMARY_PATH, WORKSPACE_ROOT)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
