    if not os.path.isfile(path):
        return make_entry(
            "file_exists_%s" % filename,
            False,
            "Expected output file is missing: outputs/%s" % filename,
        )
    return make_entry(
        "file_exists_%s" % filename,
        True,
        "Expected output file present: outputs/%s" % filename,
    )


def check_file_nonempty(filename):
    path = os.path.join(OUTPUTS_DIR, filename)
    if not os.path.isfile(path):
        return make_entry(
            "file_nonempty_%s" % filename,
            False,
            "Cannot check size because file is missing: outputs/%s" % filename,
        )
    size = os.path.getsize(path)
    if size == 0:
        return make_entry(
            "file_nonempty_%s" % filename,
            False,
            "Output file is empty (0 bytes): outputs/%s" % filename,
        )
    return make_entry(
        "file_nonempty_%s" % filename,
        True,
        "Output file is non-empty (%d bytes): outputs/%s" % (size, filename),
    )


def check_header_and_rows(filename):
    label = "header_and_rows_%s" % filename
    path = os.path.join(OUTPUTS_DIR, filename)
    if not os.path.isfile(path):
        return make_entry(label, False, "Cannot inspect header: file missing outputs/%s" % filename)
    try:
        header, row_count = read_csv_header_and_rowcount(path)
    except Exception as exc:  # report, don't crash
        return make_entry(label, False, "Failed to parse outputs/%s: %s" % (filename, exc))
    if header is None:
        return make_entry(label, False, "Output file has no header row: outputs/%s" % filename)
    required = REQUIRED_COLUMNS.get(filename, [])
    missing_cols = [col for col in required if col not in header]
    if missing_cols:
        return make_entry(
            label,
            False,
            "outputs/%s is missing required columns: %s" % (filename, ", ".join(missing_cols)),
        )
    if row_count == 0:
        return make_entry(label, False, "outputs/%s has a header but no data rows" % filename)
    return make_entry(
        label,
        True,
        "outputs/%s has %d data rows and required columns %s"
        % (filename, row_count, ", ".join(required)),
    )


def check_t01_direction_values():
    path = os.path.join(OUTPUTS_DIR, "t01_selected_indicators.csv")
    if not os.path.isfile(path):
        return make_entry("t01_direction_values", False, "File missing: outputs/t01_selected_indicators.csv")
    valid = {"higher_is_better", "lower_is_better"}
    try:
        with open(path, newline="", encoding="utf-8") as fh:
            reader = csv.DictReader(fh)
            rows = [row for row in reader if any((v or "").strip() for v in row.values())]
    except Exception as exc:
        return make_entry("t01_direction_values", False, "Failed to parse file: %s" % exc)
    bad = [row.get("expected_direction", "").strip() for row in rows if row.get("expected_direction", "").strip() not in valid]
    if bad:
        return make_entry(
            "t01_direction_values",
            False,
            "%d row(s) with invalid expected_direction values in outputs/t01_selected_indicators.csv" % len(bad),
        )
    return make_entry(
        "t01_direction_values",
        True,
        "All %d indicator rows in outputs/t01_selected_indicators.csv have valid expected_direction values" % len(rows),
    )


def check_t05_coords():
    path = os.path.join(OUTPUTS_DIR, "t05_clean_stops.csv")
    if not os.path.isfile(path):
        return make_entry("t05_stop_coordinates", False, "File missing: outputs/t05_clean_stops.csv")
    try:
        with open(path, newline="", encoding="utf-8") as fh:
            reader = csv.DictReader(fh)
            rows = [row for row in reader if any((v or "").strip() for v in row.values())]
    except Exception as exc:
        return make_entry("t05_stop_coordinates", False, "Failed to parse file: %s" % exc)
    bad = 0
    for row in rows:
        try:
            lat = float(row["stop_lat"])
            lon = float(row["stop_lon"])
        except (KeyError, TypeError, ValueError):
            bad += 1
            continue
        if not (-90.0 <= lat <= 90.0 and -180.0 <= lon <= 180.0):
            bad += 1
    if bad:
        return make_entry(
            "t05_stop_coordinates",
            False,
            "%d stop row(s) in outputs/t05_clean_stops.csv have missing or out-of-range coordinates" % bad,
        )
    return make_entry(
        "t05_stop_coordinates",
        True,
        "All %d stops in outputs/t05_clean_stops.csv have valid coordinates" % len(rows),
    )


def check_t08_poi_types():
    path = os.path.join(OUTPUTS_DIR, "t08_pois_clean.csv")
    if not os.path.isfile(path):
        return make_entry("t08_poi_types", False, "File missing: outputs/t08_pois_clean.csv")
